/* Comparateur de ratios — Sharpe vs Treynor, deux fonds */
(function () {
  var svg = document.getElementById("rt-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function activeLang(){ return document.body.getAttribute("data-active-lang") || "fr"; }

  var VERD = {
    agreeA: {fr:"→ Fonds A domine sur les deux mesures.", en:"→ Fund A wins on both measures.", nl:"→ Fonds A wint op beide maatstaven."},
    agreeB: {fr:"→ Fonds B domine sur les deux mesures.", en:"→ Fund B wins on both measures.", nl:"→ Fonds B wint op beide maatstaven."},
    flip:   {fr:"⚠ Classement inversé : un fonds gagne au Sharpe (risque total), l'autre au Treynor (risque systématique). Le « meilleur » dépend de si on le détient seul ou dans un portefeuille diversifié.",
             en:"⚠ Ranking flips: one wins on Sharpe (total risk), the other on Treynor (systematic risk). The “best” depends on holding it alone or in a diversified portfolio.",
             nl:"⚠ Rangschikking slaat om: de één wint op Sharpe (totaal risico), de ander op Treynor (systematisch risico). De “beste” hangt af van alleen aanhouden of in een gediversifieerde portefeuille."}
  };

  function draw() {
    var ra=v("rt-ra"), sa=v("rt-sa"), ba=v("rt-ba"), rb=v("rt-rb"), sb=v("rt-sb"), bb=v("rt-bb"), rf=v("rt-rf");
    setT("rt-ra-o", v("rt-ra")+"%"); setT("rt-sa-o", v("rt-sa")+"%"); setT("rt-ba-o", v("rt-ba").toFixed(2));
    setT("rt-rb-o", v("rt-rb")+"%"); setT("rt-sb-o", v("rt-sb")+"%"); setT("rt-bb-o", v("rt-bb").toFixed(2));
    setT("rt-rf-o", v("rt-rf")+"%");

    var shA=(ra-rf)/sa, shB=(rb-rf)/sb, trA=(ra-rf)/ba, trB=(rb-rf)/bb;
    setT("rt-sha", shA.toFixed(2)); setT("rt-shb", shB.toFixed(2));
    setT("rt-tra", trA.toFixed(2)); setT("rt-trb", trB.toFixed(2));

    var L=activeLang();
    var shWin = shA>shB ? "A" : "B", trWin = trA>trB ? "A" : "B";
    var vk = (shWin===trWin) ? (shWin==="A"?"agreeA":"agreeB") : "flip";
    var vEl=document.getElementById("rt-verdict");
    vEl.textContent = VERD[vk][L];
    vEl.style.color = vk==="flip" ? "var(--crimson, #b23a48)" : "var(--ink-soft)";

    // two rows of paired bars, normalised within each metric
    var W=520,H=170,L0=92,R=16,T=16, rowH=54, gap=26, barH=17;
    function bars(y, label, va, vb, winA){
      var mx=Math.max(va,vb,0.0001), full=W-L0-R;
      var wa=(va/mx)*full, wb=(vb/mx)*full;
      var g="";
      g+='<text x="'+(L0-10)+'" y="'+(y+barH)+'" text-anchor="end" fill="var(--ink-soft)" font-size="12" font-weight="700" font-family="var(--sans)">'+label+'</text>';
      function barLabel(x, yy, w, txt){
        // place label outside the bar end, or inside (white, right-aligned) if it would overflow
        if (L0+w+52 > W) return '<text x="'+(L0+w-6)+'" y="'+(yy+barH-4)+'" text-anchor="end" fill="#fff" font-size="11" font-family="var(--mono)">'+txt+'</text>';
        return '<text x="'+(L0+w+6)+'" y="'+(yy+barH-4)+'" fill="var(--ink-soft)" font-size="11" font-family="var(--mono)">'+txt+'</text>';
      }
      g+='<rect x="'+L0+'" y="'+y+'" width="'+wa.toFixed(1)+'" height="'+barH+'" fill="var(--navy)"/>';
      g+=barLabel(y, y, wa, 'A '+va.toFixed(2));
      var y2=y+barH+7;
      g+='<rect x="'+L0+'" y="'+y2+'" width="'+wb.toFixed(1)+'" height="'+barH+'" fill="#c19a3e"/>';
      g+=barLabel(y2, y2, wb, 'B '+vb.toFixed(2));
      return g;
    }
    var out="";
    out+=bars(T, "Sharpe", shA, shB);
    out+=bars(T+rowH+gap, "Treynor", trA, trB);
    svg.innerHTML=out;
  }

  ["rt-ra","rt-sa","rt-ba","rt-rb","rt-sb","rt-bb","rt-rf"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
